public class CifVariant {
    void bar(int x, int y) {
        if (x > 1) {
            {
                if (y > 1) {
                    System.out.println(x + y);
                }
            }
        }
    }
}

public class CifDeeper {
    void bar(int x, int y) {
        if (x > 1) {
            {
                {
                    if (y > 1) {
                        System.out.println(x + y);
                    }
                }
            }
        }
    }
}

public class CifSibling {
    void bar(int x, int y) {
        if (x > 1) {
            {
                int z = 5;
                if (y > 1) {
                    System.out.println(x + y);
                }
            }
        }
    }
}

public class CifComment {
    void bar(int x, int y) {
        if (x > 1) {
            {
                // keep the conditions
                if (y > 1) {
                    System.out.println(x + y);
                }
            }
        }
    }
}
